diff --git a/apps/demo-app/src/config.ts b/apps/demo-app/src/config.ts
index ad7b479..f35095f 100644
--- a/apps/demo-app/src/config.ts
+++ b/apps/demo-app/src/config.ts
@@ -8,11 +8,16 @@ const databaseSchema = z.object({
   DATABASE_URL: z.url({ protocol: /^postgres(ql)?$/ }),
 });

+// The largest value an int4 column can hold: settings are stored in `integer` columns
+// (e.g. orders.shipping_cents), so a bigger value would overflow on insert instead of
+// being refused where it is read.
+const INT4_MAX = 2_147_483_647;
+
 // The config surface the infra/config seeded bugs break.
 const shopSchema = z.object({
-  SHIPPING_FLAT_CENTS: z.coerce.number().int().min(0).default(500),
-  FREE_SHIPPING_MIN_CENTS: z.coerce.number().int().min(0).default(5000),
-  MAX_ITEM_QUANTITY: z.coerce.number().int().min(1).default(10),
+  SHIPPING_FLAT_CENTS: z.coerce.number().int().min(0).max(INT4_MAX).default(500),
+  FREE_SHIPPING_MIN_CENTS: z.coerce.number().int().min(0).max(INT4_MAX).default(5000),
+  MAX_ITEM_QUANTITY: z.coerce.number().int().min(1).max(INT4_MAX).default(10),
   CHECKOUT_ENABLED: z.stringbool().default(true),
 });

